const Review: React.FC<ReviewProps> = ({ reviewer, lessons, quote }) => (
  <div className="p-4 bg-gray-100 rounded-lg shadow-md w-80 h-64 flex flex-col justify-between">
    <div>
      <strong>{reviewer}</strong>
      <i>, {lessons} lessons.</i>
    </div>
    <div className="text-yellow-500">
      {'★'.repeat(5)} {/* 5 gold stars */}
    </div>
    <p>{quote}</p>
  </div>
);

export default Review;
